نقش سازمانی: retail_buying_manager (retail_buying_manager)

درخواست کاربر:
«کنسرو و غذای آماده» را واردت کنیم یا داخلی بخریم؟ عدد بده. (مدیر خرید — هایپراستار)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارش خرید به تفکیک تأمین‌کننده و دسته",
      "dimensions": [
        "supplier",
        "category",
        "month"
      ],
      "measures": [
        "amount_m",
        "qty_ton",
        "unit_price_k"
      ]
    },
    {
      "dataset": "supplier_scorecard",
      "description": "عملکرد تأمین‌کنندگان",
      "dimensions": [
        "supplier",
        "month"
      ],
      "measures": [
        "on_time_rate",
        "rejection_rate",
        "fill_rate"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "price_variance",
      "description": "اختلاف قیمت خرید از شاخص بازار",
      "formula": "قیمت خرید منهای شاخص",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "on_time_rate",
      "description": "تحویل به‌موقع تأمین‌کننده",
      "formula": "سفارش‌های به‌موقع تقسیم بر کل",
      "unit": "درصد",
      "dimensions": [
        "supplier"
      ]
    }
  ],
  "business_context": [
    "ارزیابی ماهانهٔ تحویل به‌موقع و مرجوعی تأمین‌کنندگان",
    "خرید مرکزی برای ۱۲۰ شعبه با مرکز توزیع واحد",
    "شاخص قیمت بازار ماهانه برای دسته‌های اصلی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "purchase_orders",
    "filters": {
      "category": "کنسرو و غذای آماده",
      "period": "last_3_months"
    }
  }
}

TOOL_OBSERVATION:
{
  "local_unit_price_k": 691,
  "monthly_qty_ton": 5100
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_scorecard",
    "filters": {
      "supplier": "گزینهٔ واردات",
      "period": "na"
    }
  }
}

TOOL_OBSERVATION:
{
  "option_import": {
    "fob_k": 443,
    "freight_k": 92,
    "customs_k": 57,
    "landed_k": 592,
    "lead_days": 68,
    "min_order_m": 16000
  },
  "option_local": {
    "unit_price_k": 691,
    "lead_days": 12
  }
}

