      "unit": "درصد",
      "dimensions": [
        "supplier"
      ]
    },
    {
      "metric": "price_variance",
      "description": "اختلاف قیمت خرید از شاخص بازار",
      "formula": "قیمت خرید منهای شاخص",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "هدف پیشروی کالا ۸۵٪ تا پایان دوره",
    "شاخص قیمت بازار ماهانه برای دسته‌های اصلی",
    "ارزیابی ماهانهٔ تحویل به‌موقع و مرجوعی تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_scorecard",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "avg_on_time_pct": 82.2,
  "top_supplier_share_pct": 48
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "price_index",
    "filters": {
      "category": [
        "شوینده و بهداشتی",
        "سرمودی و فریزری"
      ],
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "شوینده و بهداشتی": {
    "index_change_pct": -1.6
  },
  "سرمودی و فریزری": {
    "index_change_pct": 2.1
  },
  "our_price_variance_pct": 2.5
}

